import "jsr:@supabase/functions-js/edge-runtime.d.ts";
const B64="";

const originalHandler=(req)=>{const h={"Content-Type":"image/webp","Cache-Control":"public, max-age=86400","Access-Control-Allow-Origin":"*"};if(req.method==="HEAD")return new Response(null,{status:200,headers:h});if(req.method!=="GET")return new Response("Method Not Allowed",{status:405,headers:{Allow:"GET, HEAD"}});const bin=atob(B64);const out=Uint8Array.from(bin,c=>c.charCodeAt(0));return new Response(out,{status:200,headers:h});};
const COVER_B64="";
let coverBytes:Uint8Array|undefined;
Deno.serve((req:Request)=>{const k=new URL(req.url).searchParams.get('cover');if(k===null)return originalHandler(req);if(k!=="archive")return new Response('Cover not found',{status:404});if(req.method!=='GET'&&req.method!=='HEAD')return new Response('Method Not Allowed',{status:405,headers:{Allow:'GET, HEAD'}});coverBytes??=Uint8Array.from(atob(COVER_B64),c=>c.charCodeAt(0));return new Response(req.method==='HEAD'?null:coverBytes,{headers:{'content-type':'image/png','content-length':String(coverBytes.byteLength),'cache-control':'public,max-age=86400','access-control-allow-origin':'*','x-content-type-options':'nosniff'}});});